    assert.fail('expected the hook to refuse');
  } catch (error) {
    assert.ok(String(error.stderr ?? '').trim().length > 0);
  }
});

const VALID_MESSAGE = `Enforce commit message sections in commit-msg hook

✅ Hook checks for ✅❌🔄🧪 sections and rejects a 🧪 section that says "none"
❌ No known issues
🔄 Nothing left in progress
🧪 Ran \`node --test\`; all cases pass including the new hook enforcement tests
`;

test('a message with all four required sections and real test evidence is accepted', () => {
  assert.equal(check(VALID_MESSAGE), 0);
});

test('a message missing the 🧪 section is refused', () => {
  const message = VALID_MESSAGE.split('\n').filter((line) => !line.startsWith('🧪')).join('\n');
  assert.notEqual(check(message), 0);
});

test('a message missing the ✅ section is refused', () => {
  const message = VALID_MESSAGE.split('\n').filter((line) => !line.startsWith('✅')).join('\n');
  assert.notEqual(check(message), 0);
});

test('a message missing the ❌ section is refused', () => {
  const message = VALID_MESSAGE.split('\n').filter((line) => !line.startsWith('❌')).join('\n');
  assert.notEqual(check(message), 0);
});

test('a message missing the 🔄 section is refused', () => {
  const message = VALID_MESSAGE.split('\n').filter((line) => !line.startsWith('🔄')).join('\n');
  assert.notEqual(check(message), 0);
});

test('a message reports which sections are missing', () => {
  const message = 'Just a plain long enough commit message with no sections at all';
  const file = join(mkdtempSync(join(tmpdir(), 'msg-')), 'COMMIT_EDITMSG');
  writeFileSync(file, message, 'utf8');
  try {
    execFileSync('bash', ['.githooks/commit-msg', file], { stdio: 'pipe' });
    assert.fail('expected the hook to refuse');
  } catch (error) {
    const stderr = String(error.stderr ?? '');
    assert.match(stderr, /✅/);
    assert.match(stderr, /❌/);
    assert.match(stderr, /🔄/);
    assert.match(stderr, /🧪/);
  }
});

test('a 🧪 section that says "none" is refused', () => {
  const message = VALID_MESSAGE.replace(/🧪.*$/m, '🧪 none');
  assert.notEqual(check(message), 0);
});

test('a 🧪 section that says "None" is refused regardless of case', () => {
  const message = VALID_MESSAGE.replace(/🧪.*$/m, '🧪 None.');
  assert.notEqual(check(message), 0);
});

test('a 🧪 section with no content after the marker is refused', () => {
  const message = VALID_MESSAGE.replace(/🧪.*$/m, '🧪');
  assert.notEqual(check(message), 0);
});

test('a 🧪 section that describes real verification is accepted even if brief', () => {
  const message = VALID_MESSAGE.replace(/🧪.*$/m, '🧪 ran the test suite');
  assert.equal(check(message), 0);
});

